#!/usr/bin/env python3
"""Final evidence-based GPS/geometry/localizer experiment report."""
import json, re
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'outputs/gps_soft_prior_20261019'
B=json.loads((ROOT/'outputs/lidar_global_holdout_20261019/run_summary.json').read_text())
old={a['bag'][:-4]:a for a in B['heldout_runs']}
NAMES=['localization_on_20261019','localization_from2_on_20261019','localization_3_on_20261019','localization_3_off_20261019','localization_3_on_pose_limited_20261019']
def read(name):
 path=OUT/name;data=json.loads((path/'events.json').read_text());a=np.array(data['map_pose_trace'],float);dt=np.diff(a[:,0]);d=np.linalg.norm(np.diff(a[:,1:4],axis=0),axis=1);q=np.unwrap(2*np.arctan2(a[:,6],a[:,7]));dy=np.abs(np.diff(q))*180/np.pi
 good=dt>.03
 log=(path/'step3.log').read_text(errors='replace')
 return dict(name=name,completed='run_complete' in (path/'status.txt').read_text(),first_lock_wall_s=data['first_lock_wall_s_after_first_lidar'],final_status=data['last_status'],pose_count=len(a),max_step_m=float(d.max()),max_speed_mps=float(np.max(d[good]/dt[good])),p95_speed_mps=float(np.percentile(d[good]/dt[good],95)),max_yaw_rate_deg_s=float(np.max(dy[good]/dt[good])),gps_reacquire_rank_logs=log.count('[STEP3 GPS] reacquire'),gps_initial_scored_candidates=log.count('gps_distance='),pose_limit_logs=log.count('[STEP3 PUB-LIMIT]'),status=[(v['sensor_s_since_bag_start'],v['details']) for v in data['events'] if v['kind']=='status'],pose=a)
all=[read(n) for n in NAMES]; stat={r['name']:{k:v for k,v in r.items() if k!='pose'} for r in all}
(OUT/'final_validation_summary.json').write_text(json.dumps(stat,indent=2)+'\n')
A={v['name']:v for v in all}
raw=A['localization_3_on_20261019']['pose'];limited=A['localization_3_on_pose_limited_20261019']['pose']
t=np.arange(max(raw[0,0],limited[0,0]),min(raw[-1,0],limited[-1,0]),.1)
rr=np.column_stack([np.interp(t,raw[:,0],raw[:,i]) for i in [1,2,3]])
ll=np.column_stack([np.interp(t,limited[:,0],limited[:,i]) for i in [1,2,3]])
lag=np.linalg.norm(rr-ll,axis=1)
for b in [raw,limited]:
 assert (np.diff(b[:,0])>0).all()
fig,ax=plt.subplots(figsize=(9,4));ax.plot(t,lag);ax.set(xlabel='Seconds into bag',ylabel='Disagreement between replayed map poses (m)',title='Pose-limited vs unrestricted outputs: positional backlog');ax.grid(alpha=.3);fig.tight_layout();fig.savefig(OUT/'reacquisition_pose_lag.png',dpi=140);plt.close(fig)
fig,ax=plt.subplots(figsize=(9,5));ax.plot(raw[:,1],raw[:,2],label='GPS soft, default published pose');ax.plot(limited[:,1],limited[:,2],label='GPS soft + publication limiter');ax.set(xlabel='Experimental map X (m)',ylabel='Experimental map Y (m)',title='localization_3.bag map-frame pose trace (not ground truth)');ax.axis('equal');ax.legend();ax.grid(alpha=.3);fig.tight_layout();fig.savefig(OUT/'localization_3_xy_comparison.png',dpi=140);plt.close(fig)
tf=json.loads((ROOT/'outputs/camera_investigation_20261019_1533/tf_chain_audit.json').read_text())
lines=['# GPS soft-prior / LiDAR global-localization investigation','', '## Experiment contract','', '- **Map**: `maps/campus_full_lio_226s_20261019/`, 319 LiDAR keyframes from 225.52 s LiDAR-only odometry. Primary map unmodified, no surveyed alignment.', '- **Sensor/matcher**: same 0.75× ROS1 bag playback, same Scan Context + GICP thresholds and saved odometry as previous three-bag LiDAR-only benchmark.', '- **Code**: `src/step3_global_acquirer.cpp` adds opt-in `~gps_soft_prior_enable`, valid/stale/covariance checks and a *capped* penalty in candidate ranking. LiDAR geometry is always mandatory; no NavSatFix publishes a pose. Configured 25 m deadband means nearby candidates receive no GPS penalty, deliberately avoiding excessive reliance on noisy GPS.', '- **Safety**: all replays are offline, `~/Desktop/ALIVE_N/alive_dev` and original source bags/maps untouched, vehicle `/pose` NOT enabled.', '', '## Held-out results', '', '| Replay | Complete | Initial lock wall s | Final status | Maximum published step m | Maximum published speed m/s |', '|---|---|---:|---|---:|---:|']
for a in all:
 lines.append(f"| {a['name']} | {a['completed']} | {a['first_lock_wall_s']:.2f} | {a['final_status']} | {a['max_step_m']:.2f} | {a['max_speed_mps']:.2f} |")
lines+=['', '**GPS does not fix localization_3.** Its GPS-on and GPS-off runs under the SAME patched binary lock in virtually identical time (~2.94 s), both lose lock near 30–31 s, temporarily reacquire near 34 s, and finish verifying another relocalization near the end. The difference versus older 3.26 s baseline is not attributable to GPS: runtime variation and test environment differ.', '', 'The first two stable bag replays remain GLOBAL_LOCKED; GPS-on initial locks are ~3.16 s and ~3.37 s, compared with previous ~3.17 s and ~3.41 s LiDAR-only runs. No meaningful repeatable speedup established.', '', '## Why localization_3 fails', '', '- Local tracking GICP fitness progressively increases around the turn: near 30 s several candidates are >0.30 (poor under the test threshold). The matcher finds competing map keyframes across overlapping route segments; map ID differences alone are not physical distances.', '- Reacquisition selected keyframes around 63–68 and later considers 292–294; GPS at the *end* is comparatively close to the latter, so their retrieval is not on its own proof of a false positive.', '- The published pose re-anchor near 34 s involved ~13 m/9.8° residual with a short 1.5 s smoothing horizon. A large internal anchor revision cannot become physically plausible motion merely by smoothing the output.', '- Final `RELOCALIZING: verifying` is also partly **end-of-bag censored**: the system has very little additional recording after its final candidate, and the 2-consecutive-registration acceptance rule remains unsatisfied. Do not claim a persistent failure would necessarily continue on a longer recording.', '', '## Map-frame continuity / rate-limit ablation', '', f"- Raw GPS soft-prior replay: largest step {A['localization_3_on_20261019']['max_step_m']:.2f}m, max speed {A['localization_3_on_20261019']['max_speed_mps']:.2f}m/s, max yaw-rate {A['localization_3_on_20261019']['max_yaw_rate_deg_s']:.1f}deg/s.", f"- Rate-limited GPS replay: largest step {A['localization_3_on_pose_limited_20261019']['max_step_m']:.2f}m, max speed {A['localization_3_on_pose_limited_20261019']['max_speed_mps']:.2f}m/s, max yaw-rate {A['localization_3_on_pose_limited_20261019']['max_yaw_rate_deg_s']:.1f}deg/s.", f"- **Critical trade-off**: unconstrained-versus-limited published poses differ by as much as **{np.max(lag):.2f} m** during recovery, so the limiter **DOES NOT qualify /pose**. It preserves incremental motion while leaving a large temporary position error/backlog. Treat global localization as untrusted and require vehicle-level fail-closed response instead of publishing a confident navigation pose during that discrepancy.", '', '## GPS and geometric limitations', '', '- ROS1 `NavSatStatus::STATUS_FIX` is 0 (not NO_FIX). Map keyframe GPS coordinates and real held-out fixes were consumed by opt-in candidate ranking, never absolute pose correction. Candidate distances within 25 m incur zero penalty, so this coarse prior is intentionally too weak to disambiguate nearby overlapping roads in these tests.', f"- LiDAR/base inherited extrinsic disagrees with an algebraically implied TF chain by {tf['inherited_rotation_disagreement_deg']:.2f}° and {tf['inherited_translation_disagreement_m']:.2f}m, BUT the recorded camera/base identity transform may not be a surveyed mounting transform. Physical calibration remains **UNVERIFIED**; do not overwrite profile from this inference.", '- The raw LiDAR map has 23.15 m Z variation and revisit-Z p95 0.77 m; it has no surveyed alignment or 3D loop optimization.', '', '## Deliverables', '', '- `src/step3_global_acquirer.cpp`: opt-in, fail-soft GPS candidate ranking.', '- `launch/fresh_multimodal_global_rosbag.launch`: explicitly gated experimental parameters, default OFF.', '- `scripts/run_lidar_gps_soft_holdout.sh`: reproducible isolated runner; `GPS_MODE=off` provides a same-binary control; `POSE_LIMIT=true` enables continuity ablation.', '- `scripts/monitor_step3_pose_continuity.py`: records timestamped published map poses and lock events.', '- `outputs/gps_soft_prior_20261019/{final_validation_summary.json,reacquisition_pose_lag.png,localization_3_xy_comparison.png,GEOMETRY_CALIBRATION_AUDIT.md}`.', '', '**Go/no-go: NO-GO for autonomous global /pose.** Two simpler held-outs track continuously, one turns/reacquires with dangerous internal anchor ambiguity, GPS is not yet a remedy, and LiDAR–IMU physical extrinsics are unresolved.']
(OUT/'FINAL_REPORT.md').write_text('\n'.join(lines)+'\n');print('Generated',OUT/'FINAL_REPORT.md','and 2 plots. Lag max',round(np.max(lag),2),'m')
